//! Shared engine: one long-lived micro-VM running `docker:dind`.
//!
//! The engine is an ordinary container flagged `engine` (the guest init loads
//! bridge/netfilter modules, enables forwarding and, with a GPU, writes the
//! `veynodevm.dev/gpu` CDI spec). dockerd's TLS endpoint (mutual TLS, client
//! certificates generated by dind into a host-shared directory) is published
//! on host loopback. Directories given as `shares` are mounted at the same
//! path, so host bind mounts under them work. The docker context and the
//! docker CLI itself are the client's (`veynodevm engine`, `run --shared`).
use super::{
    container::{self, RunOptions},
    progress,
    util::{flag, opt_string, opt_u64},
};
use crate::{
    api_server::{Ctx, StreamIo},
    home,
};
use anyhow::{bail, Result};
use serde_json::{json, Value};
use std::{
    path::{Path, PathBuf},
    time::{Duration, Instant},
};
use veynodevm_api::{refuse, ErrorCode};

pub const NAME: &str = "veynodevm-engine";
pub const IMAGE: &str = "docker:28-dind";
pub const CONTEXT: &str = "veynodevm";
const DEFAULT_PORT: u16 = 2376;

fn certs() -> Result<PathBuf> {
    let dir = home::private_dir(&home::root()?.join("engine"))?;
    Ok(dir.join("certs"))
}

fn port(c: &container::Container) -> u16 {
    c.ports.first().map(|p| p.host_port).unwrap_or(DEFAULT_PORT)
}

fn engine() -> Result<container::Container> {
    container::find(NAME).map_err(|_| {
        refuse(
            ErrorCode::NotFound,
            "engine not created; run veynodevm engine start",
        )
    })
}

/// The engine's view: its state, endpoint, and the environment that points
/// the docker CLI at it.
fn view(c: &container::Container) -> Result<Value> {
    let (state, status) = container::status_text(c);
    let console = container::read_console(c);
    let certs = certs()?;
    Ok(json!({
        "state": state,
        "status": status,
        "endpoint": format!("tcp://127.0.0.1:{}", port(c)),
        "port": port(c),
        "context": CONTEXT,
        "gpu": console.gpu,
        "backend": c.backend,
        "certs": certs,
        "env": {
            "DOCKER_HOST": format!("tcp://127.0.0.1:{}", port(c)),
            "DOCKER_TLS_VERIFY": "1",
            "DOCKER_CERT_PATH": certs,
        },
    }))
}

/// The environment that points the docker CLI at the engine.
pub fn env() -> Result<Vec<(String, String)>> {
    let view = view(&engine()?)?;
    Ok(view["env"]
        .as_object()
        .into_iter()
        .flatten()
        .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_owned()))
        .collect())
}

pub fn status(_: &Ctx, _: Value) -> Result<Value> {
    view(&engine()?)
}

/// dind writes the client certificates when dockerd is up; the endpoint
/// accepting connections is the rest. The client checks dockerd itself.
fn wait_ready(c: &container::Container, timeout: Duration) -> Result<()> {
    let deadline = Instant::now() + timeout;
    let cert = certs()?.join("cert.pem");
    loop {
        let console = container::read_console(c);
        if let Some(code) = console.exit {
            bail!("engine exited with status {code}; see veynodevm logs {NAME}")
        }
        if cert.exists() && std::net::TcpStream::connect(("127.0.0.1", port(c))).is_ok() {
            return Ok(());
        }
        if Instant::now() > deadline {
            bail!("engine did not become ready in time; see veynodevm logs {NAME}")
        }
        std::thread::sleep(Duration::from_millis(500));
    }
}

/// A host directory shared into the engine at the same path.
fn shared_dir(dir: &str) -> Result<PathBuf> {
    let path = Path::new(dir);
    if !path.is_absolute() || !path.is_dir() || path == Path::new("/") {
        return Err(refuse(
            ErrorCode::Invalid,
            format!("shares need an existing absolute directory other than /: {dir}"),
        ));
    }
    if dir.contains(':') || dir.contains(',') {
        return Err(refuse(
            ErrorCode::Invalid,
            "a share path must not contain ':' or ','",
        ));
    }
    Ok(path.to_owned())
}

/// `engine.start`: starts the engine, creating it with these options the
/// first time.
pub fn start(_: &Ctx, args: Value, io: &StreamIo) -> Result<Value> {
    super::with_progress(io, || start_engine(&args))
}

fn start_engine(args: &Value) -> Result<Value> {
    let shares = args["shares"]
        .as_array()
        .map(|a| a.iter().filter_map(Value::as_str).map(shared_dir).collect())
        .transpose()?
        .unwrap_or_else(Vec::new);
    let gpus = opt_string(args, "gpus")?;
    let c = match container::find(NAME) {
        Ok(c) => {
            let (state, _) = container::status_text(&c);
            if !shares.is_empty() || gpus.is_some() {
                return Err(refuse(ErrorCode::State, format!("shares and gpus apply when the engine is created; run `veynodevm rm -f {NAME}` first (its images and containers are discarded)")));
            }
            if matches!(state.as_str(), "stopped" | "crashed" | "missing") {
                container::start(&c)?;
            }
            c
        }
        Err(_) => {
            let certs = certs()?;
            std::fs::create_dir_all(&certs)?;
            let port = opt_u64(args, "port")?.unwrap_or(DEFAULT_PORT.into());
            let port = u16::try_from(port)
                .map_err(|_| refuse(ErrorCode::Invalid, "port is out of range"))?;
            // Inside the engine VM, inbound segments above ~1300 bytes were
            // observed to be lost on Apple NAT while plain containers were
            // unaffected (docs/known-issues.md); 1280 is the safe default.
            let mtu = opt_u64(args, "mtu")?.unwrap_or(1280);
            let mtu = u16::try_from(mtu)
                .map_err(|_| refuse(ErrorCode::Invalid, "mtu is out of range"))?;
            let image = opt_string(args, "image")?.unwrap_or(IMAGE).to_owned();
            progress(&format!("creating shared engine ({image})"));
            container::create_and_start(&RunOptions {
                image,
                name: Some(NAME.into()),
                detach: true,
                ports: vec![format!("127.0.0.1:{port}:2376")],
                // Shared host directories keep their path, so `docker run -v`
                // and compose bind mounts under them resolve inside the VM.
                volumes: std::iter::once(format!("{}:/certs/client", certs.display()))
                    .chain(shares.iter().map(|d| format!("{0}:{0}", d.display())))
                    .collect(),
                cpus: Some(opt_u64(args, "cpus")?.unwrap_or(4) as u32),
                memory_mib: Some(opt_u64(args, "memoryMiB")?.unwrap_or(4096)),
                disk_gib: Some(opt_u64(args, "diskGiB")?.unwrap_or(64)),
                gpus: gpus.map(str::to_owned),
                engine: true,
                dns: args["dns"]
                    .as_array()
                    .map(|a| {
                        a.iter()
                            .filter_map(Value::as_str)
                            .map(String::from)
                            .collect()
                    })
                    .unwrap_or_default(),
                mtu: Some(mtu),
                // dind passes leading flags to dockerd; inner bridges match the VM.
                command: vec![format!("--mtu={mtu}")],
                quiet: flag(args, "quiet")?,
                ..Default::default()
            })?
        }
    };
    wait_ready(&c, Duration::from_secs(180))?;
    view(&c)
}

pub fn stop(_: &Ctx, _: Value) -> Result<Value> {
    container::stop(&engine()?, Duration::from_secs(20))?;
    Ok(json!({}))
}

pub fn rm(_: &Ctx, args: Value) -> Result<Value> {
    container::remove(&engine()?, flag(&args, "force")?)?;
    Ok(json!({}))
}
